 setup('''()=>{const g=__game;const c=g.entities.find(e=>e.type==='core'&&!e.team),gas=g.geysers[1],ref=g.spawn('refinery',0,gas.x,gas.y);ref.geyser=gas;g.testRef=ref.id;g.entities.filter(e=>e.type==='worker'&&!e.team).slice(0,3).forEach(w=>g.issue(w,{kind:'gas',target:ref}));g.selected=[c,ref]}''');r=page.evaluate('''()=>{const g=__game,c=g.entities.find(e=>e.type==='core'&&!e.team),r=g.entities.find(e=>e.id===g.testRef);return{mineral:g.view.workerStatuses.get(c.id),gas:g.view.workerStatuses.get(r.id)}}''');check('Mineral and gas labels distinguish worker assignments',r['mineral']['count']==9 and r['gas']['count']==3 and r['gas']['ideal']==3,r)
