 setup('''()=>{const g=__game;g.camera.x=850;g.camera.y=1000;g.view.setCamera(g.camera);const m=g.spawn('marine',0,850,970);g.stop(m,true);m.pangle=-1;m.angle=1;g.testMarine=m.id;g.selected=[m]}''');check('Rendered heading reaches simulation heading without extra exponential lag',page.evaluate('Math.abs(__game.view.objects.get(__game.testMarine).rotation.y+1)<1e-9'))
